# RhinoHealth/claude-plugins/catalog.yaml: every shared skill, its plugin and its owner.
# Owners keep their skill's evals green and run its monthly rule diet. CI checks this file against plugins/*/skills.
owners:
  platform: { slack: "<agents channel ID>" } # no Platform team on GitHub yet (Sean and Shai)
  shai: { github: "<Shai's GitHub login>" }
  fe-guild: { github: "@RhinoHealth/frontend-guild" }
  be-guild: { github: "@RhinoHealth/backend-guild" }
  devops: { github: "@RhinoHealth/devops" }
  security: { slack: "<Ronen's Slack ID>" }
skills:
  plan-and-grill: { plugin: rhino-core, owner: platform }
  verify: { plugin: rhino-core, owner: [platform, shai] }
  pr-story: { plugin: rhino-core, owner: [platform, shai] }
  fix-bug: { plugin: rhino-core, owner: [fe-guild, be-guild] }
